// spec: specs/location-map.md 3.5 · кейс .qa/tests/location-map/PRIV-02.md · только просмотр
import { test, expect } from '@playwright/test';
import path from 'path';
import { saveSession } from '../_shared/session';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free.json') });

test.describe('פרטיות מיקום — экран разрешения', () => {
  test.afterEach(async ({ page }) => saveSession(page, 'free'));
  test('/permissions обещает «המיקום המדויק שלך לא מוצג לאף אחד» и предлагает доступ к месту @iphone @prod-safe (#f3fc59)', async ({ page }) => {
    await page.goto('/permissions');
    await expect(page.getByText('מי נמצא לידך עכשיו?')).toBeVisible();
    // п.8: обещание экрана соответствует поведению (точные координаты другим не отдаются — см. approx-coords-privacy).
    await expect(page.getByText(/המיקום המדויק שלך לא מוצג לאף אחד/)).toBeVisible();
    await expect(page.getByRole('button', { name: 'אפשר/י גישה למיקום' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'לא עכשיו' })).toBeVisible();
  });
});
